INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('毒氟磷', '{"component":"毒氟磷","ph":"7.62（中性）","contraindications":"【作物限制】登记作物：水稻、烟草、番茄、玉米、西瓜、百香果等；发病前或初期施药效果最佳\n【混配限制】不能与碱性物质混用；药液应随配随用，不能久存；遇酸和碱均逐渐分解"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('戊唑醇', '{"component":"戊唑醇","ph":"6.0-7.0（中性偏酸）","contraindications":"【作物限制】瓜类苗期慎用，易产生药害；梨树某些品种敏感\n【混配限制】不可与碱性农药（石硫合剂、波尔多液、铜制剂）混用；不可与强酸性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('丙环唑', '{"component":"丙环唑","ph":"5.5-6.5（弱酸性）","contraindications":"【作物限制】瓜类苗期、幼果期慎用；葡萄幼果期易产生药害；草莓花期慎用\n【混配限制】不可与碱性农药混用；不建议与有机磷杀虫剂混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('苯醚甲环唑', '{"component":"苯醚甲环唑","ph":"5.0-6.0（弱酸性）","contraindications":"【作物限制】瓜类苗期慎用；对某些梨品种敏感\n【混配限制】不可与铜制剂、碱性农药混用；与乳油类农药混用需降低浓度"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('三唑酮', '{"component":"三唑酮","ph":"6.0-7.0（中性）","contraindications":"【作物限制】瓜类苗期慎用\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('己唑醇', '{"component":"己唑醇","ph":"6.0-7.0（中性）","contraindications":"【作物限制】瓜类苗期慎用；苹果某些品种早期慎用\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('烯唑醇', '{"component":"烯唑醇","ph":"6.0-7.0（中性）","contraindications":"【作物限制】瓜类苗期禁用；对某些苹果品种有药害\n【混配限制】不可与碱性农药混用"}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_pesticide_extras (component, payload_json, updated_at) VALUES ('氟硅唑', '{"component":"氟硅唑","ph":"5.0-6.0（弱酸性）","contraindications":"【作物限制】瓜类苗期慎用；梨树盛花期慎用\n【混配限制】不可与碱性农药、铜制剂混用"}', '2026-08-22T01:14:46.869Z');
